SELECT COUNT(*) FROM cms_claim_request
WHERE article_id = #{articleId}
  AND applicant_id = #{applicantId}
  AND status IN ('PENDING', 'APPROVED')

SELECT COUNT(*) FROM cms_claim_request
WHERE article_id = #{articleId}
  AND status IN ('PENDING', 'APPROVED')

SELECT COUNT(*) FROM cms_claim_request
WHERE article_id = #{articleId}
  AND applicant_id = #{applicantId}
  AND status = 'APPROVED'

SELECT FROM cms_claim_request c JOIN cms_article a ON a.id = c.article_id JOIN sys_user u ON u.id = c.applicant_id LEFT JOIN sys_user rv ON rv.id = c.reviewer_id
AND c.status = #{status} AND c.article_id = #{itemId}
ORDER BY c.created_at DESC, c.id DESC
